    // somebody actually named, sitting at the running count for that price.
    // The static figure above carries the same dots and they matter more than
    // the line, so they are drawn on top with a white ring to stay legible.
    Plot.line(staircase, {x: "wtp", y: "quantity", curve: "step-before",
                          stroke: "#2563EB", strokeWidth: 2}),
    Plot.dot(staircase, {x: "wtp", y: "quantity", r: nresp > 80 ? 2.8 : 4,
